import json
import logging
import uuid

LOGGER = logging.getLogger()
LOGGER.setLevel(logging.INFO)

VALID_SIZES = ("small", "medium", "large")
VALID_CRUSTS = ("thin", "thick")
VALID_TOPPINGS = ("pepperoni", "mushroom", "sausage", "onion", "olives", "bacon")
MIN_QUANTITY = 1
MAX_QUANTITY = 20


def elicit_slot(session_attributes, intent_name, slots, slot_to_elicit, message):
    return {
        "sessionAttributes": session_attributes,
        "dialogAction": {
            "type": "ElicitSlot",
            "intentName": intent_name,
            "slots": slots,
            "slotToElicit": slot_to_elicit,
            "message": {"contentType": "PlainText", "content": message},
        },
    }


def close(session_attributes, fulfillment_state, message):
    return {
        "sessionAttributes": session_attributes,
        "dialogAction": {
            "type": "Close",
            "fulfillmentState": fulfillment_state,
            "message": {"contentType": "PlainText", "content": message},
        },
    }


def normalize(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def parse_quantity(value):
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    if number < MIN_QUANTITY or number > MAX_QUANTITY:
        return None
    return number


def handler(event, context):
    LOGGER.info("Received event: %s", json.dumps(event))

    intent_name = event["currentIntent"]["name"]
    slots = dict(event["currentIntent"].get("slots") or {})
    session_attributes = dict(event.get("sessionAttributes") or {})

    pizza_size = normalize(slots.get("pizza_size"))
    pizza_crust = normalize(slots.get("pizza_crust"))
    pizza_toppings = normalize(slots.get("pizza_toppings"))
    quantity = parse_quantity(slots.get("quantity"))

    if pizza_size and pizza_size not in VALID_SIZES:
        slots["pizza_size"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_size",
            "What size pizza would you like - small, medium, or large?",
        )

    if pizza_crust and pizza_crust not in VALID_CRUSTS:
        slots["pizza_crust"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_crust",
            "What kind of crust would you like - thin or thick?",
        )

    if pizza_toppings and pizza_toppings not in VALID_TOPPINGS:
        slots["pizza_toppings"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_toppings",
            "Which topping would you like - pepperoni, mushroom, sausage, onion, olives, or bacon?",
        )

    if quantity is None:
        slots["quantity"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "quantity",
            "How many pizzas would you like? Please give me a number between 1 and 20.",
        )

    slots["pizza_size"] = pizza_size
    slots["pizza_crust"] = pizza_crust
    slots["pizza_toppings"] = pizza_toppings
    slots["quantity"] = str(quantity)

    order_id = str(uuid.uuid4())
    session_attributes["orderId"] = order_id

    summary = (
        "Order {order_id} confirmed: {quantity} {size} pizza with {crust} crust "
        "and {toppings} toppings. Your pizza is on the way!"
    ).format(
        order_id=order_id,
        quantity=quantity,
        size=pizza_size,
        crust=pizza_crust,
        toppings=pizza_toppings,
    )

    LOGGER.info("Fulfilled pizza order %s", order_id)
    return close(session_attributes, "Fulfilled", summary)

